document.addEventListener('DOMContentLoaded', () => {
    const observationForm = document.getElementById('observation-form');
    const observationList = document.getElementById('observation-list');
    const observationCountDisplay = document.getElementById('observation-count');
    const emptyStateMessage = document.getElementById('empty-state');

    let observations = [];

    function updateObservationCount() {
        observationCountDisplay.textContent = `Total Observations: ${observations.length}`;
        if (observations.length === 0) {
            emptyStateMessage.style.display = 'block';
        } else {
            emptyStateMessage.style.display = 'none';
        }
    }

    function createObservationCard(obs) {
        const card = document.createElement('blockquote');
        card.innerHTML = `<h3>${obs.title}</h3><p><strong>Location:</strong> ${obs.location}</p><p>${obs.note}</p>`;
        observationList.appendChild(card);
    }

    function addObservation(event) {
        event.preventDefault();

        const titleInput = document.getElementById('observation-title');
        const locationInput = document.getElementById('observation-location');
        const noteInput = document.getElementById('observation-note');

        const newObservation = {
            title: titleInput.value.trim(),
            location: locationInput.value.trim(),
            note: noteInput.value.trim()
        };

        if (newObservation.title && newObservation.location && newObservation.note) {
            observations.push(newObservation);
            renderObservations();
            observationForm.reset();
            updateObservationCount();
        } else {
            alert('Please fill in all fields.');
        }
    }

    function renderObservations() {
        observationList.innerHTML = '';
        observations.forEach(obs => {
            createObservationCard(obs);
        });
    }

    observationForm.addEventListener('submit', addObservation);

    // Initial render (will show empty state)
    updateObservationCount();
});

